"""AgentMemory - Persistent memory system for AI agents."""
import json
import os
from datetime import datetime
from pathlib import Path
from typing import List, Dict, Any, Optional

class AgentMemory:
    """Persistent memory system for remembering facts, learning lessons, and tracking entities."""

    def __init__(self, db_path: Optional[str] = None):
        """Initialize AgentMemory with optional custom database path."""
        if db_path:
            self.db_path = Path(db_path)
        else:
            self.db_path = Path.home() / ".agent-memory" / "memory.db"

        self._ensure_db_exists()

    def _ensure_db_exists(self):
        """Create database file if it doesn't exist."""
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        if not self.db_path.exists():
            self._save({"facts": [], "lessons": [], "entities": []})

    def _load(self) -> Dict[str, Any]:
        """Load memory from database."""
        if self.db_path.exists():
            return json.loads(self.db_path.read_text(encoding='utf-8'))
        return {"facts": [], "lessons": [], "entities": []}

    def _save(self, data: Dict[str, Any]):
        """Save memory to database."""
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self.db_path.write_text(json.dumps(data, indent=2), encoding='utf-8')

    def remember(self, fact: str, tags: Optional[List[str]] = None) -> str:
        """Remember an important fact."""
        data = self._load()
        entry = {
            "fact": fact,
            "tags": tags or [],
            "timestamp": datetime.now().isoformat()
        }
        data["facts"].append(entry)
        self._save(data)
        return entry["timestamp"]

    def learn(self, action: str, context: str, outcome: str, insight: str) -> str:
        """Learn from an experience."""
        data = self._load()
        entry = {
            "action": action,
            "context": context,
            "outcome": outcome,
            "insight": insight,
            "timestamp": datetime.now().isoformat()
        }
        data["lessons"].append(entry)
        self._save(data)
        return entry["timestamp"]

    def recall(self, query: str) -> List[str]:
        """Recall facts matching the query."""
        data = self._load()
        results = []
        query_lower = query.lower()
        for fact in data["facts"]:
            if query_lower in fact["fact"].lower():
                results.append(fact["fact"])
        return results

    def get_lessons(self, context: Optional[str] = None, limit: Optional[int] = None) -> List[Dict[str, Any]]:
        """Get lessons, optionally filtered by context."""
        data = self._load()
        lessons = data["lessons"]
        if context:
            context_lower = context.lower()
            lessons = [l for l in lessons if context_lower in l["context"].lower()]
        if limit:
            lessons = lessons[-limit:]
        return lessons

    def track_entity(self, name: str, entity_type: str, attributes: Optional[Dict[str, Any]] = None) -> str:
        """Track an entity (person, project, etc.)."""
        data = self._load()
        entry = {
            "name": name,
            "type": entity_type,
            "attributes": attributes or {},
            "timestamp": datetime.now().isoformat()
        }
        # Update existing entity or add new one
        existing = next((e for e in data["entities"] if e["name"] == name), None)
        if existing:
            existing["attributes"].update(entry["attributes"])
            existing["timestamp"] = entry["timestamp"]
        else:
            data["entities"].append(entry)
        self._save(data)
        return entry["timestamp"]

    def get_entity(self, name: str) -> Optional[Dict[str, Any]]:
        """Get an entity by name."""
        data = self._load()
        for entity in data["entities"]:
            if entity["name"] == name:
                return entity
        return None

    def get_all(self) -> Dict[str, Any]:
        """Get all memory data."""
        return self._load()
EOF\n",
